import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse(`{"title":"Page 32 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"32","title":"Page 32 | Home","prev":"/page/31/","next":"/page/33/","posts":[{"title":"使用Postfix,Dovecot和Mysql配置邮件服务器","url":"/posts/2014-12-25-configure-mail-server/","date":"2014-12-25 15:41","tags":["notes"],"html":"<p>由于学习的需要,我要配置个本地邮件服务器.虽然找到了一篇很详细的资料,但是在配置过程中还是遇到了这样那样的问题.\\n写篇文章记下来自己的学习过程,毕竟好记性不如烂笔头嘛.</p>\\n<h2 id=\\"详细教程\\" tabindex=\\"-1\\">详细教程 <a class=\\"header-anchor\\" href=\\"#详细教程\\" aria-label=\\"Permalink to &quot;详细教程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Google 一下便找到了一个十分详细的教程,分享给大家:<a href=\\"https://www.digitalocean.com/community/tutorials/how-to-configure-a-mail-server-using-postfix-dovecot-mysql-and-spamassasin\\" target=\\"_blank\\" rel=\\"noreferrer\\">How To Configure a Mail Server Using Postfix, Dovecot, MySQL, and SpamAssasin</a>\\n教程虽然很详细,但难免有不理解和差错的地方.下面就讲下我遇到的问题:</p>\\n<h2 id=\\"dovecot-证书问题\\" tabindex=\\"-1\\">Dovecot 证书问题 <a class=\\"header-anchor\\" href=\\"#dovecot-证书问题\\" aria-label=\\"Permalink to &quot;Dovecot 证书问题&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>教程上设置的证书位置是:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>ssl_cert = &#x3C;/etc/ssl/certs/dovecot.pem</span></span>\\n<span class=\\"line\\"><span>ssl_key = &#x3C;/etc/ssl/private/dovecot.pem</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>但实际上是空的 需要手动 copy 过去,默认存储的位置是:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>ssl_cert = /etc/dovecot/dovecot.pem</span></span>\\n<span class=\\"line\\"><span>ssl_key = /etc/dovecot/private/dovecot.pem</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><h2 id=\\"查看日志发现读取配置出错\\" tabindex=\\"-1\\">查看日志发现读取配置出错 <a class=\\"header-anchor\\" href=\\"#查看日志发现读取配置出错\\" aria-label=\\"Permalink to &quot;查看日志发现读取配置出错&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>出错信息如下:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>dovecot: lmtp(11504): Fatal: Error reading configuration: Invalid settings: postmaster_address setting not given</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>查到相关资料<a href=\\"https://github.com/mail-in-a-box/mailinabox/issues/31\\" target=\\"_blank\\" rel=\\"noreferrer\\">Invalid settings: postmaster_address setting not given</a>\\n简单来说就是在<code>/etc/dovecot/dovecot.conf</code>文件内添加一行 <code>postmaster_address=postmaster at DOMAIN</code> 即可</p>\\n<h2 id=\\"重启-dovecot\\" tabindex=\\"-1\\">重启 Dovecot <a class=\\"header-anchor\\" href=\\"#重启-dovecot\\" aria-label=\\"Permalink to &quot;重启 Dovecot&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当我们执行 <code>service dovecot restart</code> 时,发现根本没有这个 service.<br>\\n其实 dovecot 已经在运行了,我们只需执行 <code>dovecot reload</code> 即可</p>\\n<h2 id=\\"邮件无法发送\\" tabindex=\\"-1\\">邮件无法发送 <a class=\\"header-anchor\\" href=\\"#邮件无法发送\\" aria-label=\\"Permalink to &quot;邮件无法发送&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>日志输出如下:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>B0E4F26077E: to=&#x3C;root@example.jp>, orig_to=&#x3C;root>, relay=none, delay=6780, delays=6780/0/0.09/0, dsn=5.4.4, status=bounced (Host or domain name not found. Name service error for name=example.jp type=AAAA: Host not found)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个问题是因为 Postfix 默认启用了 IPv6 并且优先级比 IPv4 要高,所以需要在配置文件 <code>/etc/postfix/main.cf</code>里面设置\\n<code>inet_protocols = ipv4</code> 这样就关闭 IPv6 了.即可解决问题.</p>\\n<p>大概就是遇到这么多问题了,最后祝愿大家圣诞节快乐~</p>\\n"},{"title":"JavaScript处理二进制数据","url":"/posts/2014-11-23-javascript-binary/","date":"2014-11-23 14:30","tags":["js"],"html":"<p>最近在开发扩展的时候遇到需要获取 MP3 数据并且直接交给其它接口处理的问题,但是使用 JQuery 的 AJAX 进行\\n获取数据的时候已经把数据进行了编码,毕竟默认都是处理文本数据.<br>\\n但是我需要的是二进制数据并且进行 Base64 编码方便进行传输,因为 Base64 编码的值全是可打印字符.\\nBase64 常用于在通常处理文本数据的场合,表示、传输、存储一些二进制数据.</p>\\n<h2 id=\\"二进制数据转换成-base64-编码\\" tabindex=\\"-1\\">二进制数据转换成 Base64 编码 <a class=\\"header-anchor\\" href=\\"#二进制数据转换成-base64-编码\\" aria-label=\\"Permalink to &quot;二进制数据转换成 Base64 编码&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>于是便找到了一个非常有用的 MDN 的文档<a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/XMLHttpRequest/Sending_and_Receiving_Binary_Data\\" target=\\"_blank\\" rel=\\"noreferrer\\">Sending and Receiving Binary Data</a><br>\\n不过稍作修改:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> oReq </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> XMLHttpRequest</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">open</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'GET'</span><span style=\\"color:#24292E\\">, request.data, </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.responseType </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'blob'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">onload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">oEvent</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> blob </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> oReq.response;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> reader </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> FileReader</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  reader.</span><span style=\\"color:#6F42C1\\">onload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">readerEvt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> binaryString </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> readerEvt.target.result;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">    // console.log(binaryString);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> testdata </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> btoa</span><span style=\\"color:#24292E\\">(binaryString);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      method: </span><span style=\\"color:#032F62\\">'getAudio'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      data: </span><span style=\\"color:#032F62\\">'data:audio/mp3;base64,'</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#6F42C1\\"> btoa</span><span style=\\"color:#24292E\\">(binaryString)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    port.</span><span style=\\"color:#6F42C1\\">postMessage</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  reader.</span><span style=\\"color:#6F42C1\\">readAsBinaryString</span><span style=\\"color:#24292E\\">(blob);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">oReq.</span><span style=\\"color:#6F42C1\\">send</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br></div></div><p>设置 responseType 为<a href=\\"https://developer.mozilla.org/en/docs/Web/API/Blob\\" target=\\"_blank\\" rel=\\"noreferrer\\">Blob</a>\\n然后使用 FileReader 作为二进制数据读取,再使用 btoa 转码成 Base64 进行传输.</p>\\n<p>还有一种是读取需要上传的文件进行处理的方式和通过 AJAX 获取的方式差不多,代码在<a href=\\"http://jsfiddle.net/eliseosoto/JHQnk/\\" target=\\"_blank\\" rel=\\"noreferrer\\">这里</a>.使用 Base64 编码的好处是在需要二进制数据的地方,例如图片和音频,我们可以使用 Base64 编码进行替换获取这些资源的 URL\\n可以减少 HTTP 请求,也可以做转发,我之所以有这个处理二进制数据的需求就是因为开发的一个插件无法在 HTTPS 页面上获取 HTTP 资源,\\n便通过 background js 进行获取数据然后 Base64 编码传输给 content js 进行使用.</p>\\n<h2 id=\\"base64-数据转换为-arraybuffer\\" tabindex=\\"-1\\">Base64 数据转换为 ArrayBuffer <a class=\\"header-anchor\\" href=\\"#base64-数据转换为-arraybuffer\\" aria-label=\\"Permalink to &quot;Base64 数据转换为 ArrayBuffer&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有时候需要把传入的二进制数据转换成 ArrayBuffer 进行处理就需要转换了</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> atob</span><span style=\\"color:#24292E\\">(base64String);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> dataView </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Uint8Array</span><span style=\\"color:#24292E\\">(data.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> data.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">i) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  dataView[i] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> data.</span><span style=\\"color:#6F42C1\\">charCodeAt</span><span style=\\"color:#24292E\\">(i);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> arrayBuffer </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> dataView.buffer;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>今天暂时就写这么多吧,期末考试看书好累,头脑都不太清醒了. QAQ</p>\\n"},{"title":"扇贝单词助手发布","url":"/posts/2014-10-30-shanbay-helper/","date":"2014-10-30 18:30","tags":["notes"],"html":"<p>最近受菊苣<a href=\\"https://plus.google.com/u/0/+RoyBinux/\\" target=\\"_blank\\" rel=\\"noreferrer\\">binux</a>的要求,希望能开发一款扇贝网的<a href=\\"https://chrome.google.com/webstore/detail/shanbayhelper/mbekldhkbpihlaogjpclihoobhoakcic\\" target=\\"_blank\\" rel=\\"noreferrer\\">单词助手</a>,可以标记任意页面上已经背过的单词.项目源码在<a href=\\"https://github.com/acgotaku/ShanBayHelper\\" target=\\"_blank\\" rel=\\"noreferrer\\">Github</a>.\\n然后我就趁着国庆就开坑了,binux 也给了我很多参考资料.因为之前也开发过 Chrome 的扩展,所以对 Chrome 提供的 API 比较熟悉.这里就介绍下使用的相关的 JavaScript 的知识吧~</p>\\n<h2 id=\\"promise\\" tabindex=\\"-1\\">Promise <a class=\\"header-anchor\\" href=\\"#promise\\" aria-label=\\"Permalink to &quot;Promise&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Promise 是用来处理大量的异步操作,因为异步操作不能直接 return 返回值,必须进行回调.所以就会导致很多异步操作在一起不断的进行嵌套,这样实在是很不优雅的代码书写方式.代码首先是用来给人读的,其次才是可以运行.使用 Promise 就可以把多个异步操作的返回值以数组的形式返回来,然后再进行回调.语言描述不好,还是上例子吧.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> get_cookie</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">site</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">name</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#005CC5\\"> Promise</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">resolve</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">reject</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    chrome.cookies.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">({ url: site, name: name }, </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">cookies</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (cookies) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        var</span><span style=\\"color:#24292E\\"> data </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> cookies.name </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> '='</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> cookies.value;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        resolve</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        reject</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><p>Chrome 的 API 全部是异步操作,所以我一开始使用 return 的时候并没有得到值.把回调函数封装到一个 Promise 对象里面,然后传入两个参数 resolve,reject 分别代表异步操作成功执行或失败需要调用的函数.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> site1 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://pan.baidu.com/'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> name1 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'BDUSS'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> site2 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://pcs.baidu.com/'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> name2 </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'pcsett'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">Promise</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">all</span><span style=\\"color:#24292E\\">([</span><span style=\\"color:#6F42C1\\">get_cookie</span><span style=\\"color:#24292E\\">(site1, name1), </span><span style=\\"color:#6F42C1\\">get_cookie</span><span style=\\"color:#24292E\\">(site2, name2)]).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">value</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(value);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  function</span><span style=\\"color:#24292E\\"> () {}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>这里我们需要调用两次异步操作,一般情况的话需要函数嵌套,但是使用 Promise 对象的话,只需要在 then 里面需要写上 resolve 和 reject 需要的执行函数,\\n传入的 value 就是两次异步操作的返回值数组.然后就可以进行相关的处理.代码就变得清晰有条理.</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Mozilla/JavaScript_code_modules/Promise.jsm/Promise\\" target=\\"_blank\\" rel=\\"noreferrer\\">Promise 文档</a></p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Promise/all\\" target=\\"_blank\\" rel=\\"noreferrer\\">Promise.all</a></p>\\n"}]},"relativePath":"page/32/index.md","filePath":"page/[page].md"}`),e={name:"page/32/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const b=s(e,[["render",l]]);export{d as __pageData,b as default};
